			/**
			 * 플로팅 위치 계산
			 */
			function calcFloatPort() {
			    
			    //캘린더가 float되어야 할 위치를 계산
			    var voRootContainer = app.getRootAppInstance().getContainer();
			    var voViewPort = voRootContainer.getViewPortRect();
			    var vcSipb = app.lookup("sipb1");
			    var voOffset = vcSipb.getActualRect();    
			        
			    //아래에 float시킬지 여부
			    var vbIsBottomFloat = true;
			    var vbIsLeftFloat = true;
			    var voFloatPort = {
			        top: "0px",
			        left: "0px"
			    }
			    
			    //캘린더가 아래에 위치해야하는지 여부   
			    vbIsBottomFloat = voOffset.top + voOffset.height + mnCalHeight > voViewPort.height ? (voOffset.top - mnCalHeight < 0 ? true : false) : true;
			    voFloatPort.top = vbIsBottomFloat ? voOffset.top + voOffset.height + "px" : voOffset.top - mnCalHeight + "px";
			    
			    //캘린더가 왼쪽에 위치해야 하는지 여부
			    vbIsLeftFloat = voOffset.left + mnCalWidth > voViewPort.width ? (voOffset.right - mnCalWidth < 0 ? true : false) : true;
			    voFloatPort.left = vbIsLeftFloat ? voOffset.left + "px" : voOffset.right - mnCalWidth + "px";
			    
			    return voFloatPort;
			}

			//=================================================================================
			// [Control Event Function]
			//=================================================================================

			/*
			 * 라디오 버튼에서 selection-change 이벤트 발생 시 호출.
			 * 라디오버튼 아이템을 선택하여 선택된 값이 저장된 후에 발생하는 이벤트.
			 */
			function onRdb1SelectionChange(e) {
			    var rdb1 = e.control;
			    var vcSipb1 = app.lookup("sipb1");
			    
			    if (rdb1.value == "value1") { // 전일
			        vcSipb1.visible = false;
			        vcSipb1.value = ""
			    } else { // 일자 선택
			        vcSipb1.visible = true;
			    }
			}

			/*
			 * 서치 인풋에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onSipb1Click2(e) {
			    var sipb1 = e.control;
			    
			    var voOffset = sipb1.getActualRect();
			    var voFloatPort = calcFloatPort(); // 플로팅될 위치를 계산합니다.
			    
			    // 플로팅 시킬 캘린더 컨트롤을 생성합니다.    
			    var vcCal = new cpr.controls.Calendar("cal");
			    vcCal.selectionType = "multiple"; // 다중선택
			    
			    // blur 이벤트에서 컨트롤 삭제
			    vcCal.addEventListener("blur", onCalBlur);
			    // date-click 이벤트에서 서치인풋에 value 추가
			    vcCal.addEventListener("date-click", onCalDateClick);
			    
			    // 플로팅될 캘린더의 스타일 적용    
			    vcCal.style.css({
			        "position": "absolute",
			        "top": voFloatPort.top,
			        "left": voFloatPort.left,
			        "width": mnCalWidth + "px",
			        "height": mnCalHeight + "px"
			    });
			    
			    // 캘린더 데이터 셋팅
			    if(!ValueUtil.isNull(sipb1.value)){
			        // 기존에 선택된 데이터가 있으면 캘린더에 values 적용
			        var vaValues = sipb1.value.split(",");
			        vcCal.values = vaValues;
			    } else {
			        vcCal.values = [];
			    }
			    
			    // 캘린더 min, max Date 설정
			    var vcRangePicker = app.lookup("cmnDaterangePicker");
			    var vsStartDate = vcRangePicker.startDate;
			    var vsEndDate = vcRangePicker.endDate;
			   
			    if(!ValueUtil.isNull(vsStartDate)) vcCal.minDate = moment(vsStartDate).toDate();
			    if(!ValueUtil.isNull(vsEndDate)) vcCal.maxDate = moment(vsEndDate).toDate();
			            
			    // 캘린더를 플로팅 시킨다
			    app.getRootAppInstance().floatControl(vcCal);
			    vcCal.visible = true; 
			    vcCal.focus(); // 플로팅된 캘린더로 포커스 이동(추후 blur 처리를 통한 visible 처리)
			}


			/*
			 * 캘린더에서 blur 이벤트 발생 시 호출.
			 * 컨트롤이 포커스를 잃은 후 발생하는 이벤트.
			 */
			function onCalBlur(e){
			    /**@type cpr.controls.Calendar*/
			    var cal1 = e.control;
			                
			    //캘린더 컨트롤 제거 
			    cal1.dispose();
			}

			/*
			 * 캘린더에서 date-click 이벤트 발생 시 호출.
			 * Calendar의 날짜를 클릭 했을때 발생하는 이벤트.
			 */
			function onCalDateClick(e){
			    var cal1 = e.control;
			    
			    var vaValues = cal1.values;    
			    if(vaValues.length == 0) return;
			    
			    var vcSipb = app.lookup("sipb1");  
			    vcSipb.value = vaValues.toString();
			};
